/****** Object:  StoredProcedure [dbo].[sp_ProcessOrderAtomic]    Script Date: 7/24/2026 9:22:05 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[sp_ProcessOrderAtomic]
    @UserID INT,
    @ProductVariantID INT,
    @Quantity INT,
    @UnitPrice DECIMAL(18,2),
    @ShippingAddress NVARCHAR(500),
    @CustomerName NVARCHAR(100),
    @CustomerPhone VARCHAR(20),
    @PaymentMethod NVARCHAR(100),
    @IsOrderSuccess BIT OUTPUT 
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @CurrentStock INT;
        
        SELECT @CurrentStock = StockQuantity 
        FROM [dbo].[ProductVariants] WITH (UPDLOCK, HOLDLOCK)
        WHERE ProductVariantID = @ProductVariantID;

        IF @CurrentStock IS NULL OR @CurrentStock < @Quantity
        BEGIN
            ROLLBACK TRANSACTION;
            SET @IsOrderSuccess = 0;
            RETURN;
        END

        UPDATE [dbo].[ProductVariants]
        SET StockQuantity = StockQuantity - @Quantity,
            Version = Version + 1
        WHERE ProductVariantID = @ProductVariantID;

        DECLARE @InsertedOrderID INT;
        INSERT INTO [dbo].[Orders] (UserID, TotalAmount, OrderDate, Status, ShippingAddress, CustomerName, CustomerPhone, PaymentMethod, PaymentStatus)
        VALUES (@UserID, (@Quantity * @UnitPrice), GETDATE(), N'Chờ xác nhận', @ShippingAddress, @CustomerName, @CustomerPhone, @PaymentMethod, N'Chưa thanh toán');
        
        SET @InsertedOrderID = SCOPE_IDENTITY();

        INSERT INTO [dbo].[OrderDetails] (OrderID, ProductID, ProductVariantID, Quantity, UnitPrice)
        SELECT @InsertedOrderID, ProductID, ProductVariantID, @Quantity, @UnitPrice
        FROM [dbo].[ProductVariants]
        WHERE ProductVariantID = @ProductVariantID;

        COMMIT TRANSACTION;
        SET @IsOrderSuccess = 1;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @IsOrderSuccess = 0;
    END CATCH
END;

GO


